import json, os, stat, sys
from pathlib import Path
if len(sys.argv)!=3 or sys.argv[1]!='case': raise SystemExit(125)
fd=os.open(Path('/tmp/parity-home/ready-case.json'),os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC)
try:
 st=os.fstat(fd)
 if not stat.S_ISREG(st.st_mode) or st.st_uid!=2000 or st.st_nlink!=1 or st.st_size>512: raise ValueError('bad ready file')
 raw=os.read(fd,513)
finally: os.close(fd)
doc=json.loads(raw)
if set(doc)!={'pid','address','port'} or doc['pid']!=int(sys.argv[2]) or doc['address']!='127.0.0.1' or type(doc['port']) is not int or not 1<=doc['port']<=65535: raise ValueError('bad ready identity')
print(doc['port'])

